import { createServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(__dirname, "data", "books.json");
const PORT = Number(process.env.PORT) || 3000;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

async function loadBooks() {
  try {
    const raw = await readFile(DATA_PATH, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_PATH), { recursive: true });
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n", "utf8");
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.45; color: #1c1917; }
    h1 { font-size: 1.6rem; margin-bottom: 0.25rem; }
    h2 { font-size: 1.1rem; margin: 1.75rem 0 0.5rem; }
    a { color: #1d4ed8; }
    form { display: grid; gap: 0.6rem; margin: 1rem 0 2rem; }
    label { display: grid; gap: 0.2rem; font-size: 0.9rem; }
    input, textarea { font: inherit; padding: 0.4rem 0.5rem; }
    button { font: inherit; width: fit-content; padding: 0.4rem 0.8rem; cursor: pointer; }
    ul { padding-left: 1.2rem; }
    li { margin: 0.35rem 0; }
    .muted { color: #57534e; }
    .row { display: flex; gap: 0.75rem; align-items: center; flex-wrap: wrap; }
    .notes { white-space: pre-wrap; }
  </style>
</head>
<body>
  <p><a href="/">Reading list</a></p>
  ${body}
</body>
</html>`;
}

function bookList(books) {
  if (books.length === 0) return `<p class="muted">None yet.</p>`;
  return `<ul>${books
    .map(
      (book) =>
        `<li><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a> <span class="muted">by ${escapeHtml(book.author)}</span></li>`
    )
    .join("")}</ul>`;
}

function homePage(books) {
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");
  return layout(
    "Reading list",
    `<h1>Reading list</h1>
    <h2>Currently reading</h2>
    ${bookList(reading)}
    <h2>Finished</h2>
    ${bookList(finished)}
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="4"></textarea></label>
      <button type="submit">Add book</button>
    </form>`
  );
}

function bookPage(book) {
  const finished = book.status === "finished";
  return layout(
    book.title,
    `<h1>${escapeHtml(book.title)}</h1>
    <p>by ${escapeHtml(book.author)}</p>
    <p class="muted">${finished ? "Finished" : "Currently reading"}</p>
    <h2>Notes</h2>
    <p class="notes">${book.notes ? escapeHtml(book.notes) : '<span class="muted">No notes yet.</span>'}</p>
    ${
      finished
        ? ""
        : `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
            <button type="submit">Mark as finished</button>
          </form>`
    }`
  );
}

function notFound() {
  return layout("Not found", `<h1>Not found</h1><p>That book isn't on the list.</p>`);
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

function parseForm(body) {
  return Object.fromEntries(new URLSearchParams(body));
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (method === "GET" && path === "/") {
      send(res, 200, homePage(await loadBooks()));
      return;
    }

    if (method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      const title = (form.title || "").trim();
      const author = (form.author || "").trim();
      if (!title || !author) {
        send(res, 400, layout("Missing fields", `<h1>Title and author are required.</h1>`));
        return;
      }
      const books = await loadBooks();
      books.push({
        id: randomUUID(),
        title,
        author,
        notes: (form.notes || "").trim(),
        status: "reading",
      });
      await saveBooks(books);
      res.writeHead(303, { Location: "/" });
      res.end();
      return;
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (method === "POST" && finishMatch) {
      const id = decodeURIComponent(finishMatch[1]);
      const books = await loadBooks();
      const book = books.find((item) => item.id === id);
      if (!book) {
        send(res, 404, notFound());
        return;
      }
      book.status = "finished";
      await saveBooks(books);
      res.writeHead(303, { Location: `/books/${encodeURIComponent(id)}` });
      res.end();
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (method === "GET" && bookMatch) {
      const id = decodeURIComponent(bookMatch[1]);
      const book = (await loadBooks()).find((item) => item.id === id);
      if (!book) {
        send(res, 404, notFound());
        return;
      }
      send(res, 200, bookPage(book));
      return;
    }

    send(res, 404, notFound());
  } catch (err) {
    send(res, 500, layout("Error", `<h1>Something went wrong</h1><p>${escapeHtml(err.message)}</p>`));
  }
});

server.listen(PORT, () => {
  console.log(`Reading list at http://localhost:${PORT}`);
});

